// Core types for AI Commit Context

export interface SessionEvent {
  uuid: string;
  parentUuid: string | null;
  timestamp: string;
  type: 'user' | 'assistant' | 'system';
}

export interface UserMessage extends SessionEvent {
  type: 'user';
  message: {
    role: 'user';
    content: string;
  };
}

export interface ToolUse {
  type: 'tool_use';
  id: string;
  name: string;
  input: Record<string, unknown>;
}

export interface ToolResult {
  type: 'tool_result';
  tool_use_id: string;
  content: string;
}

export interface TextBlock {
  type: 'text';
  text: string;
}

export type ContentBlock = TextBlock | ToolUse | ToolResult;

export interface AssistantMessage extends SessionEvent {
  type: 'assistant';
  message: {
    role: 'assistant';
    content: string | ContentBlock[];
  };
}

export type ClaudeMessage = UserMessage | AssistantMessage;

export interface Session {
  id: string;
  projectPath: string;
  projectName: string;
  startedAt: Date;
  endedAt: Date | null;
  messageCount: number;
  filesModified: string[];
  uploaded: boolean;
  uploadUrl: string | null;
}

export interface SessionFile {
  id?: number;
  sessionId: string;
  filePath: string;
  operation: 'read' | 'write' | 'edit';
  timestamp: Date;
}

export interface SessionCommit {
  sessionId: string;
  commitSha: string;
  repoPath: string;
  createdAt: Date;
}

export interface WatcherConfig {
  claudeProjectsPath: string;
  pollInterval: number;
  dbPath: string;
}

export interface Config {
  auth: {
    token: string | null;
    apiUrl: string;
  };
  preferences: {
    autoUpload: boolean;
    privacyMode: 'public' | 'team' | 'private';
    redactSecrets: boolean;
    includeToolOutputs: boolean;
  };
  hooks: {
    enabled: boolean;
    autoLink: boolean;
    trailerFormat: string;
  };
}

export const DEFAULT_CONFIG: Config = {
  auth: {
    token: null,
    apiUrl: 'https://api.aicommitcontext.dev',
  },
  preferences: {
    autoUpload: true,
    privacyMode: 'private',
    redactSecrets: true,
    includeToolOutputs: false,
  },
  hooks: {
    enabled: true,
    autoLink: true,
    trailerFormat: 'AI-Context-ID',
  },
};

import Database from 'better-sqlite3';
import path from 'path';
import os from 'os';
import fs from 'fs';
import type { Session, SessionFile, SessionCommit } from '../types.js';

const ACC_DIR = path.join(os.homedir(), '.acc');
const DB_PATH = path.join(ACC_DIR, 'sessions.db');

// Ensure .acc directory exists
if (!fs.existsSync(ACC_DIR)) {
  fs.mkdirSync(ACC_DIR, { recursive: true });
}

const db = new Database(DB_PATH);

// Initialize database schema
export function initDatabase(): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS sessions (
      id TEXT PRIMARY KEY,
      project_path TEXT NOT NULL,
      project_name TEXT,
      started_at DATETIME,
      ended_at DATETIME,
      message_count INTEGER DEFAULT 0,
      uploaded BOOLEAN DEFAULT FALSE,
      upload_url TEXT
    );

    CREATE TABLE IF NOT EXISTS session_files (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id TEXT REFERENCES sessions(id),
      file_path TEXT NOT NULL,
      operation TEXT NOT NULL,
      timestamp DATETIME,
      UNIQUE(session_id, file_path, timestamp)
    );

    CREATE TABLE IF NOT EXISTS session_commits (
      session_id TEXT REFERENCES sessions(id),
      commit_sha TEXT NOT NULL,
      repo_path TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      PRIMARY KEY(session_id, commit_sha)
    );

    CREATE INDEX IF NOT EXISTS idx_files_session ON session_files(session_id);
    CREATE INDEX IF NOT EXISTS idx_files_path ON session_files(file_path);
    CREATE INDEX IF NOT EXISTS idx_commits_sha ON session_commits(commit_sha);
  `);
}

// Session operations
export function insertSession(session: Omit<Session, 'uploaded' | 'uploadUrl'>): void {
  const stmt = db.prepare(`
    INSERT OR REPLACE INTO sessions (id, project_path, project_name, started_at, ended_at, message_count)
    VALUES (?, ?, ?, ?, ?, ?)
  `);

  stmt.run(
    session.id,
    session.projectPath,
    session.projectName,
    session.startedAt.toISOString(),
    session.endedAt?.toISOString() || null,
    session.messageCount
  );
}

export function getSession(id: string): Session | null {
  const stmt = db.prepare('SELECT * FROM sessions WHERE id = ?');
  const row = stmt.get(id) as Record<string, unknown> | undefined;

  if (!row) return null;

  return {
    id: row.id as string,
    projectPath: row.project_path as string,
    projectName: row.project_name as string,
    startedAt: new Date(row.started_at as string),
    endedAt: row.ended_at ? new Date(row.ended_at as string) : null,
    messageCount: row.message_count as number,
    filesModified: getSessionFiles(row.id as string).map(f => f.filePath),
    uploaded: Boolean(row.uploaded),
    uploadUrl: row.upload_url as string | null,
  };
}

export function getAllSessions(limit = 50): Session[] {
  const stmt = db.prepare(`
    SELECT * FROM sessions
    ORDER BY started_at DESC
    LIMIT ?
  `);
  const rows = stmt.all(limit) as Record<string, unknown>[];

  return rows.map(row => ({
    id: row.id as string,
    projectPath: row.project_path as string,
    projectName: row.project_name as string,
    startedAt: new Date(row.started_at as string),
    endedAt: row.ended_at ? new Date(row.ended_at as string) : null,
    messageCount: row.message_count as number,
    filesModified: getSessionFiles(row.id as string).map(f => f.filePath),
    uploaded: Boolean(row.uploaded),
    uploadUrl: row.upload_url as string | null,
  }));
}

export function updateSessionUploaded(id: string, uploadUrl: string): void {
  const stmt = db.prepare(`
    UPDATE sessions SET uploaded = TRUE, upload_url = ? WHERE id = ?
  `);
  stmt.run(uploadUrl, id);
}

// Session files operations
export function insertSessionFile(file: Omit<SessionFile, 'id'>): void {
  const stmt = db.prepare(`
    INSERT OR IGNORE INTO session_files (session_id, file_path, operation, timestamp)
    VALUES (?, ?, ?, ?)
  `);

  stmt.run(
    file.sessionId,
    file.filePath,
    file.operation,
    file.timestamp.toISOString()
  );
}

export function getSessionFiles(sessionId: string): SessionFile[] {
  const stmt = db.prepare('SELECT * FROM session_files WHERE session_id = ?');
  const rows = stmt.all(sessionId) as Record<string, unknown>[];

  return rows.map(row => ({
    id: row.id as number,
    sessionId: row.session_id as string,
    filePath: row.file_path as string,
    operation: row.operation as 'read' | 'write' | 'edit',
    timestamp: new Date(row.timestamp as string),
  }));
}

export function getSessionsByFile(filePath: string): Session[] {
  const stmt = db.prepare(`
    SELECT DISTINCT s.* FROM sessions s
    JOIN session_files sf ON s.id = sf.session_id
    WHERE sf.file_path = ?
    ORDER BY s.started_at DESC
  `);
  const rows = stmt.all(filePath) as Record<string, unknown>[];

  return rows.map(row => ({
    id: row.id as string,
    projectPath: row.project_path as string,
    projectName: row.project_name as string,
    startedAt: new Date(row.started_at as string),
    endedAt: row.ended_at ? new Date(row.ended_at as string) : null,
    messageCount: row.message_count as number,
    filesModified: getSessionFiles(row.id as string).map(f => f.filePath),
    uploaded: Boolean(row.uploaded),
    uploadUrl: row.upload_url as string | null,
  }));
}

// Session commits operations
export function insertSessionCommit(commit: SessionCommit): void {
  const stmt = db.prepare(`
    INSERT OR IGNORE INTO session_commits (session_id, commit_sha, repo_path, created_at)
    VALUES (?, ?, ?, ?)
  `);

  stmt.run(
    commit.sessionId,
    commit.commitSha,
    commit.repoPath,
    commit.createdAt.toISOString()
  );
}

export function getCommitSessions(commitSha: string): Session[] {
  const stmt = db.prepare(`
    SELECT s.* FROM sessions s
    JOIN session_commits sc ON s.id = sc.session_id
    WHERE sc.commit_sha = ?
  `);
  const rows = stmt.all(commitSha) as Record<string, unknown>[];

  return rows.map(row => ({
    id: row.id as string,
    projectPath: row.project_path as string,
    projectName: row.project_name as string,
    startedAt: new Date(row.started_at as string),
    endedAt: row.ended_at ? new Date(row.ended_at as string) : null,
    messageCount: row.message_count as number,
    filesModified: getSessionFiles(row.id as string).map(f => f.filePath),
    uploaded: Boolean(row.uploaded),
    uploadUrl: row.upload_url as string | null,
  }));
}

export function getActiveSession(): Session | null {
  const stmt = db.prepare(`
    SELECT * FROM sessions
    WHERE ended_at IS NULL
    ORDER BY started_at DESC
    LIMIT 1
  `);
  const row = stmt.get() as Record<string, unknown> | undefined;

  if (!row) return null;

  return {
    id: row.id as string,
    projectPath: row.project_path as string,
    projectName: row.project_name as string,
    startedAt: new Date(row.started_at as string),
    endedAt: null,
    messageCount: row.message_count as number,
    filesModified: getSessionFiles(row.id as string).map(f => f.filePath),
    uploaded: Boolean(row.uploaded),
    uploadUrl: row.upload_url as string | null,
  };
}

// Initialize on import
initDatabase();

export { db, DB_PATH, ACC_DIR };

