import fs from 'fs';
import readline from 'readline';
import path from 'path';
import type { ClaudeMessage, ContentBlock, ToolUse, Session, SessionFile } from '../types.js';

interface ParsedSession {
  id: string;
  projectPath: string;
  messages: ClaudeMessage[];
  filesModified: SessionFile[];
  startedAt: Date;
  endedAt: Date | null;
}

/**
 * Parse a Claude Code JSONL session file
 */
export async function parseSessionFile(filePath: string): Promise<ParsedSession | null> {
  if (!fs.existsSync(filePath)) {
    return null;
  }

  const messages: ClaudeMessage[] = [];
  const filesModified: SessionFile[] = [];
  let sessionId = '';
  let startedAt: Date | null = null;
  let endedAt: Date | null = null;

  const fileStream = fs.createReadStream(filePath);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity,
  });

  for await (const line of rl) {
    if (!line.trim()) continue;

    try {
      const entry = JSON.parse(line);

      // Extract session ID from first message
      if (!sessionId && entry.uuid) {
        sessionId = entry.uuid;
      }

      // Track timestamps
      if (entry.timestamp) {
        const timestamp = new Date(entry.timestamp);
        if (!startedAt || timestamp < startedAt) {
          startedAt = timestamp;
        }
        if (!endedAt || timestamp > endedAt) {
          endedAt = timestamp;
        }
      }

      // Parse message
      if (entry.type === 'user' || entry.type === 'assistant') {
        messages.push(entry as ClaudeMessage);

        // Extract file operations from assistant messages
        if (entry.type === 'assistant' && entry.message?.content) {
          const content = entry.message.content;
          if (Array.isArray(content)) {
            for (const block of content as ContentBlock[]) {
              if (block.type === 'tool_use') {
                const toolUse = block as ToolUse;
                const fileOp = extractFileOperation(toolUse, entry.timestamp);
                if (fileOp) {
                  filesModified.push({
                    sessionId,
                    ...fileOp,
                  });
                }
              }
            }
          }
        }
      }
    } catch {
      // Skip malformed lines
      continue;
    }
  }

  if (!sessionId || messages.length === 0) {
    return null;
  }

  // Extract project path from file location
  const projectPath = path.dirname(path.dirname(filePath));

  return {
    id: sessionId,
    projectPath,
    messages,
    filesModified,
    startedAt: startedAt || new Date(),
    endedAt,
  };
}

/**
 * Extract file operation from a tool use block
 */
function extractFileOperation(
  toolUse: ToolUse,
  timestamp: string
): Omit<SessionFile, 'sessionId' | 'id'> | null {
  const input = toolUse.input as Record<string, unknown>;

  switch (toolUse.name) {
    case 'Read':
      if (input.file_path) {
        return {
          filePath: input.file_path as string,
          operation: 'read',
          timestamp: new Date(timestamp),
        };
      }
      break;

    case 'Write':
      if (input.file_path) {
        return {
          filePath: input.file_path as string,
          operation: 'write',
          timestamp: new Date(timestamp),
        };
      }
      break;

    case 'Edit':
    case 'MultiEdit':
      if (input.file_path) {
        return {
          filePath: input.file_path as string,
          operation: 'edit',
          timestamp: new Date(timestamp),
        };
      }
      break;
  }

  return null;
}

/**
 * Get all session files from Claude projects directory
 */
export function getClaudeSessionFiles(claudeProjectsPath: string): string[] {
  if (!fs.existsSync(claudeProjectsPath)) {
    return [];
  }

  const sessionFiles: string[] = [];

  const projects = fs.readdirSync(claudeProjectsPath);
  for (const project of projects) {
    const projectDir = path.join(claudeProjectsPath, project);
    if (!fs.statSync(projectDir).isDirectory()) continue;

    const files = fs.readdirSync(projectDir);
    for (const file of files) {
      if (file.endsWith('.jsonl')) {
        sessionFiles.push(path.join(projectDir, file));
      }
    }
  }

  return sessionFiles;
}

/**
 * Convert parsed session to database session format
 */
export function toSession(parsed: ParsedSession): Omit<Session, 'uploaded' | 'uploadUrl'> {
  return {
    id: parsed.id,
    projectPath: parsed.projectPath,
    projectName: path.basename(parsed.projectPath),
    startedAt: parsed.startedAt,
    endedAt: parsed.endedAt,
    messageCount: parsed.messages.length,
    filesModified: [...new Set(parsed.filesModified.map(f => f.filePath))],
  };
}

/**
 * Extract conversation text (user messages only) for summary
 */
export function extractConversationText(messages: ClaudeMessage[]): string {
  return messages
    .filter(m => m.type === 'user')
    .map(m => {
      if (typeof m.message.content === 'string') {
        return m.message.content;
      }
      return '';
    })
    .join('\n\n');
}

/**
 * Get a summary of the session (first user message truncated)
 */
export function getSessionSummary(messages: ClaudeMessage[], maxLength = 100): string {
  const firstUserMessage = messages.find(m => m.type === 'user');
  if (!firstUserMessage) return 'Empty session';

  const content = firstUserMessage.message.content;
  const text = typeof content === 'string' ? content : 'Complex message';

  if (text.length <= maxLength) {
    return text;
  }

  return text.substring(0, maxLength - 3) + '...';
}

import chokidar from 'chokidar';
import path from 'path';
import os from 'os';
import fs from 'fs';
import { parseSessionFile, toSession } from '../parser/index.js';
import { insertSession, insertSessionFile, getSession } from '../db/index.js';
import type { WatcherConfig } from '../types.js';

const DEFAULT_CLAUDE_PATH = path.join(os.homedir(), '.claude', 'projects');

interface WatcherState {
  isRunning: boolean;
  watcher: chokidar.FSWatcher | null;
  processedFiles: Set<string>;
  lastModified: Map<string, number>;
}

const state: WatcherState = {
  isRunning: false,
  watcher: null,
  processedFiles: new Set(),
  lastModified: new Map(),
};

/**
 * Start watching Claude Code session files
 */
export function startWatcher(config?: Partial<WatcherConfig>): void {
  if (state.isRunning) {
    console.log('Watcher is already running');
    return;
  }

  const claudePath = config?.claudeProjectsPath || DEFAULT_CLAUDE_PATH;

  if (!fs.existsSync(claudePath)) {
    console.log(`Claude projects directory not found: ${claudePath}`);
    console.log('Creating directory...');
    fs.mkdirSync(claudePath, { recursive: true });
  }

  console.log(`Starting watcher on: ${claudePath}`);

  state.watcher = chokidar.watch(path.join(claudePath, '**/*.jsonl'), {
    persistent: true,
    ignoreInitial: false,
    awaitWriteFinish: {
      stabilityThreshold: 1000,
      pollInterval: 100,
    },
  });

  state.watcher
    .on('add', (filePath) => handleFileChange(filePath, 'add'))
    .on('change', (filePath) => handleFileChange(filePath, 'change'))
    .on('error', (error) => console.error('Watcher error:', error));

  state.isRunning = true;
  console.log('Watcher started successfully');
}

/**
 * Stop the watcher
 */
export async function stopWatcher(): Promise<void> {
  if (!state.isRunning || !state.watcher) {
    console.log('Watcher is not running');
    return;
  }

  await state.watcher.close();
  state.watcher = null;
  state.isRunning = false;
  console.log('Watcher stopped');
}

/**
 * Handle file add/change events
 */
async function handleFileChange(filePath: string, event: 'add' | 'change'): Promise<void> {
  try {
    // Check if file was recently processed
    const stats = fs.statSync(filePath);
    const lastMod = state.lastModified.get(filePath);

    if (lastMod && stats.mtimeMs === lastMod) {
      return; // No actual change
    }

    state.lastModified.set(filePath, stats.mtimeMs);

    console.log(`[${event}] Processing: ${path.basename(filePath)}`);

    const parsed = await parseSessionFile(filePath);
    if (!parsed) {
      console.log(`  Skipped: Could not parse file`);
      return;
    }

    // Check if session already exists
    const existing = getSession(parsed.id);
    if (existing && event === 'add') {
      console.log(`  Skipped: Session already indexed`);
      return;
    }

    // Insert/update session
    const session = toSession(parsed);
    insertSession(session);

    // Insert file operations
    for (const file of parsed.filesModified) {
      insertSessionFile(file);
    }

    console.log(`  Indexed: ${parsed.messages.length} messages, ${parsed.filesModified.length} file ops`);
  } catch (error) {
    console.error(`  Error processing ${filePath}:`, error);
  }
}

/**
 * Scan all existing sessions (initial indexing)
 */
export async function scanAllSessions(claudePath?: string): Promise<number> {
  const projectsPath = claudePath || DEFAULT_CLAUDE_PATH;

  if (!fs.existsSync(projectsPath)) {
    console.log('Claude projects directory not found');
    return 0;
  }

  let count = 0;
  const projects = fs.readdirSync(projectsPath);

  for (const project of projects) {
    const projectDir = path.join(projectsPath, project);
    if (!fs.statSync(projectDir).isDirectory()) continue;

    const files = fs.readdirSync(projectDir);
    for (const file of files) {
      if (!file.endsWith('.jsonl')) continue;

      const filePath = path.join(projectDir, file);
      await handleFileChange(filePath, 'add');
      count++;
    }
  }

  return count;
}

/**
 * Get watcher status
 */
export function getWatcherStatus(): { running: boolean; path: string } {
  return {
    running: state.isRunning,
    path: DEFAULT_CLAUDE_PATH,
  };
}

export { DEFAULT_CLAUDE_PATH };

