import express from 'express';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { nanoid } from 'nanoid';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3456;

// Data storage
const DATA_DIR = path.join(__dirname, '..', 'data');
const SESSIONS_FILE = path.join(DATA_DIR, 'sessions.json');

// Ensure data directory exists
if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
}

// Types
interface Message {
  uuid: string;
  parentUuid: string | null;
  timestamp: string;
  type: 'user' | 'assistant';
  message: {
    role: string;
    content: string | ContentBlock[];
  };
}

interface ContentBlock {
  type: string;
  text?: string;
  name?: string;
  input?: unknown;
}

interface StoredSession {
  id: string;
  shortCode: string;
  projectName: string;
  uploadedAt: string;
  startedAt: string;
  endedAt: string | null;
  messageCount: number;
  messages: Message[];
  filesModified: string[];
  commits: CommitLink[];
}

interface CommitLink {
  sha: string;
  repoUrl: string;
  message: string;
  linkedAt: string;
}

interface SessionsStore {
  sessions: Record<string, StoredSession>;
}

// Load/save sessions
function loadSessions(): SessionsStore {
  if (!fs.existsSync(SESSIONS_FILE)) {
    return { sessions: {} };
  }
  try {
    return JSON.parse(fs.readFileSync(SESSIONS_FILE, 'utf-8'));
  } catch {
    return { sessions: {} };
  }
}

function saveSessions(store: SessionsStore): void {
  fs.writeFileSync(SESSIONS_FILE, JSON.stringify(store, null, 2));
}

// Middleware
app.use(cors());
app.use(express.json({ limit: '50mb' }));

// Serve static web files
app.use(express.static(path.join(__dirname, '..', '..', 'web')));

// =============================================================================
// API Routes
// =============================================================================

// Health check
app.get('/api/health', (_req, res) => {
  res.json({ status: 'ok', version: '0.1.0' });
});

// Upload session
app.post('/api/sessions', (req, res) => {
  try {
    const { sessionId, projectName, startedAt, endedAt, messages, filesModified } = req.body;

    if (!sessionId || !messages) {
      res.status(400).json({ error: 'Missing required fields: sessionId, messages' });
      return;
    }

    const store = loadSessions();
    const shortCode = nanoid(8);

    const session: StoredSession = {
      id: sessionId,
      shortCode,
      projectName: projectName || 'Unknown Project',
      uploadedAt: new Date().toISOString(),
      startedAt: startedAt || new Date().toISOString(),
      endedAt: endedAt || null,
      messageCount: messages.length,
      messages,
      filesModified: filesModified || [],
